style.css:
* {
    font-family: "Arial Black", Arial, sans-serif !important;
    font-weight: 900 !important;
}

/* ===== ⚡ ESTILO POKÉMON ===== */

/* TÍTULOS */
h1, h2, h3, h4 {
    color: #ffde00 !important;

    text-shadow:
        3px 3px 0 #3155b5,
        -2px -2px 0 #3155b5,
        4px 4px 0 #111 !important;

    letter-spacing: 1px !important;
}

/* TEXTO GENERAL */
p, span, label {
    text-shadow: 2px 2px 0 #222 !important;
}

/* BOTONES */
button {
    color: white !important;

    background: #3b5cca !important;

    border: 3px solid #182d72 !important;
    border-radius: 12px !important;

    text-shadow:
        2px 2px 0 #182d72 !important;

    box-shadow:
        0 4px 0 #182d72 !important;
}

/* BOTÓN AL PASAR EL MOUSE */
button:hover {
    background: #ffde00 !important;
    color: #3155b5 !important;

    border-color: #b28b00 !important;

    text-shadow:
        2px 2px 0 white !important;

    transform: scale(1.03) !important;
}

/* BOTÓN AL HACER CLICK */
button:active {
    transform: translateY(4px) !important;
    box-shadow: none !important;
}

/* CAJAS DE TEXTO */
input,
textarea,
select {
    background: white !important;
    color: #3155b5 !important;

    border: 3px solid #3155b5 !important;
    border-radius: 8px !important;

    font-weight: 900 !important;
}

/* TEXTO IMPORTANTE */
[class*="title"],
[class*="Title"] {
    color: #ffde00 !important;

    text-shadow:
        3px 3px 0 #3155b5,
        4px 4px 0 #111 !important;
}

/* NOMBRES */
[class*="name"],
[class*="Name"] {
    color: #3155b5 !important;

    text-shadow:
        2px 2px 0 white,
        3px 3px 0 #111 !important;
}

/* NÚMEROS / PUNTOS */
[class*="score"],
[class*="Score"],
[class*="points"],
[class*="Points"] {
    color: #ffde00 !important;

    text-shadow:
        2px 2px 0 #3155b5,
        3px 3px 0 #111 !important;
}

/* SELECCIÓN */
::selection {
    background: #3155b5 !important;
    color: #ffde00 !important;
}
